const year=()=>month.slice(0,4);
const planData=()=>ensurePlan(state,year());
const settings=()=>({...planData().settings,taxYear:Number(year())});
const budget=()=>budgetFor(state,month);
const planned=()=>{const r=F.calculatePlan(settings(),budget());if(r.complete)return r;if(r.missing.every(m=>m.startsWith('budget['))){const partial=F.calculatePlan(settings(),budget().map(b=>({...b,amount:b.amount??0})));return {...partial,complete:false,missing:r.missing,feasible:null};}return r;};
const emergency=()=>{const r=F.emergencyPlan(settings(),budget());if(r.complete)return r;const known=sum(budget().filter(b=>b.essential).map(b=>b.amount));if(known>0&&r.missing.every(m=>m==='essentialMonthly'))return {...F.emergencyPlan({...settings(),essentialMonthly:known},budget()),complete:false,provisional:true,missing:r.missing};return r;};
const ledger=(period=month)=>F.summarizeTransactions(state.transactions,period);
const snapshot=()=>state.snapshots[month]||null;
const worth=()=>{const s=snapshot();if(!s)return{assets:null,liabilities:null,netWorth:null};const n=F.netWorth(s.assets,s.liabilities);if(!s.confirmed)return {...n,assets:s.assets.length?n.assets:null,liabilities:s.liabilities.length?n.liabilities:null,netWorth:null};return n;};
