const shortMonth=m=>new Intl.DateTimeFormat(locale(),{month:'short'}).format(new Date(m+'-01T12:00:00'));
const input=(name,label,value=null,opts={})=>`<div class="field ${opts.wide?'span-2':''}"><label for="${esc(name)}">${label}</label><input id="${esc(name)}" name="${esc(name)}" type="${opts.type||'number'}" value="${esc(value??'')}" ${opts.type==='text'?'maxlength="160"':`min="${opts.min??0}" max="${opts.max??1000000000000}" step="${opts.step??'0.01'}"`} ${opts.required?'required':''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}>${opts.help?`<span class="field-help">${opts.help}</span>`:''}</div>`;
const select=(name,label,value,options,help='')=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>${help?`<span class="field-help">${help}</span>`:''}</div>`;
const button=(text,action,cls='secondary',ico='',attrs='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico,17):''}${text}</button>`;
const link=(text,route,cls='secondary',ico='')=>`<a class="button ${cls}" href="#${route}">${ico?icon(ico,17):''}${text}</a>`;
const stat=(label,value,foot,ico='wallet',featured=false)=>`<div class="stat-card ${featured?'featured':''}"><div class="stat-label">${label}<span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`;
const card=(title,subtitle,body,action='')=>`<section class="card"><div class="card-head"><div><h2 class="card-title">${title}</h2>${subtitle?`<p class="card-subtitle">${subtitle}</p>`:''}</div>${action}</div><div class="card-body">${body}</div></section>`;
const head=(eyebrow,title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-description">${desc}</p></div><div class="page-actions no-print">${actions}</div></div>`;
