function renderPage(){const views={account:accountView,dashboard:dashboardView,budget:budgetView,buckets:bucketsView,transactions:transactionsView,streams:streamsView,networth:networthView,goals:goalsView,projection:projectionView,debt:debtView,tax:taxView,health:healthView,reports:reportsView,workbook:workbookView,guide:guideView,settings:settingsView};if(!views[page])page='dashboard';$('#view').innerHTML=(page==='dashboard'?welcome():'')+(page==='guide'?usageGuide()+'<details class="guide-section"><summary>อ่านแผนการเงินและเช็กลิสต์ 30 วันเพิ่มเติม</summary><div>'+guideView()+'</div></details>':views[page]()+helpFor(page));simplifyCards($('#view'),page);renderTutorial();}
function lineChart(series,labels,height=220){
 const values=series.flatMap(s=>s.values).filter(v=>v!==null&&Number.isFinite(v));if(!values.length)return empty('กราฟจะเติบโตไปพร้อมกับคุณ','บันทึกยอดสิ้นเดือนเพื่อเห็นพัฒนาการของเงิน');
 const min=Math.min(0,...values),max=Math.max(1,...values),span=max-min;const w=720,h=height,pad=40;const y=v=>h-pad-(v-min)/span*(h-pad-16);const x=i=>pad+i*(w-pad-16)/Math.max(1,labels.length-1);
 const grid=Array.from({length:4},(_,i)=>{const v=min+span*i/3;return `<line x1="${pad}" y1="${y(v)}" x2="${w-8}" y2="${y(v)}" stroke="var(--border)" stroke-dasharray="3 5"/><text x="${pad-7}" y="${y(v)+4}" text-anchor="end" class="chart-label">${Math.abs(v)>=1000?money(v/1000,0)+'k':money(v)}</text>`;}).join('');
 const lines=series.map(s=>{let active=false;const d=s.values.map((v,i)=>{if(v===null||!Number.isFinite(v)){active=false;return '';}const cmd=active?'L':'M';active=true;return `${cmd}${x(i)},${y(v)}`;}).join(' ');return `<path d="${d}" fill="none" stroke="${s.color}" stroke-width="3" stroke-linejoin="round"/>${s.values.map((v,i)=>v===null||!Number.isFinite(v)?'':`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="${s.color}"><title>${esc(labels[i])}: ${baht(v)}</title></circle>`).join('')}`;}).join('');
 return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="กราฟ ${series.map(s=>esc(s.label)).join(', ')}">${grid}${lines}${labels.map((l,i)=>`<text x="${x(i)}" y="${h-9}" text-anchor="middle" class="chart-label">${esc(l)}</text>`).join('')}</svg><div class="legend">${series.map(s=>`<span><i class="legend-dot" style="background:${s.color}"></i>${s.label}</span>`).join('')}</div>`;
}
function dashboardView(){const p=planned(),e=emergency(),a=ledger(),n=worth();const knownCosts=sum(budget().map(b=>b.amount));const left=p.spendingLimit===null?null:p.spendingLimit-knownCosts;const unknown=budget().filter(b=>b.amount===null).length;
 const months=Array.from({length:12},(_,i)=>year()+'-'+String(i+1).padStart(2,'0'));
 const curve=months.map(m=>state.snapshots[m]?.confirmed?F.netWorth(state.snapshots[m].assets,state.snapshots[m].liabilities).netWorth:null);
 const currentRows=[...state.transactions].filter(t=>t.date.startsWith(month)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
 return head('YOUR MONEY, WITH CLARITY','ภาพรวมการเงิน','ทุกบาทมีหน้าที่ ทุกเป้าหมายมีแผน · '+monthName(month),link('ดูรายงาน','reports','secondary','book')+button('เพิ่มรายการ','add-transaction','primary','plus'))+
 `<section class="hero-banner"><div class="hero-copy"><div class="hero-kicker"><span class="legend-dot" style="background:#bef0a9"></span> PAY YOURSELF FIRST</div><h2 class="hero-title">เก็บก่อนใช้<br>ให้อนาคตมั่นคงขึ้นทุกเดือน</h2><p class="hero-description">เป้าหมายออม ${money(settings().savingsRate)}% ของเงินเดือนก่อนหัก<br>เริ่มจากเงินสำรองฉุกเฉิน แล้วค่อยเติบโตไปกับการลงทุน</p>${link('จัดสรรกองเงิน','buckets','secondary','arrow')}</div><div class="hero-art"><svg viewBox="0 0 280 205" role="img" aria-label="เป้าหมายออม ${money(settings().savingsRate)} เปอร์เซ็นต์"><circle cx="156" cy="100" r="72" fill="none" stroke="#ffffff18" stroke-width="21"/><circle cx="156" cy="100" r="72" fill="none" stroke="#c8efb1" stroke-width="21" stroke-dasharray="${452*Math.min(100,settings().savingsRate)/100} 452" transform="rotate(-90 156 100)" stroke-linecap="round"/><text x="156" y="101" fill="white" font-size="41" font-weight="700" text-anchor="middle">${money(settings().savingsRate)}%</text><text x="156" y="124" fill="#d9ebe4" font-size="12" text-anchor="middle">เป้าหมายการออม</text><rect x="9" y="158" width="164" height="35" rx="11" fill="#fff"/><text x="91" y="181" fill="#175f49" font-size="12" text-anchor="middle">✦ Emergency fund first</text></svg></div></section>`+
 `<div class="stat-grid">${stat('รายได้ตามแผน / เดือน',baht(p.grossIncome),'ก่อนหัก · ยังไม่ใช่รายรับจริง','briefcase')}${stat('เป้าหมายเก็บก่อนใช้',baht(p.savings),money(settings().savingsRate)+'% จากเงินเดือน + แผนรายได้เสริม','layers',true)}${stat('วงเงินใช้จ่าย',baht(p.spendingLimit),'หลังหักเงินออม ภาษี และรายการหัก','wallet')}${stat('ความมั่งคั่งสุทธิ',baht(n.netWorth),snapshot()?(snapshot().confirmed?'ทรัพย์สิน − หนี้สิน ณ เดือนที่เลือก':'ยอดที่บันทึก · ยังไม่ยืนยันครบ'):'ยังไม่บันทึกงบทรัพย์สินและ กยศ.','chart')}</div>`+
 `<div class="dashboard-grid"><div class="section-stack">${card('เส้นทางความมั่งคั่ง','ยอดจริงสิ้นเดือน · ปี '+(calendarYear(year())),lineChart([{label:'ความมั่งคั่งสุทธิ',color:'#24775d',values:curve}],months.map(shortMonth)),link('บันทึกยอด','networth','ghost small','plus'))}${card('รายการล่าสุด','รายการจริงในเดือนที่เลือก',currentRows.length?transactionTable(currentRows,false):empty('สมุดบัญชีเล่มใหม่ของคุณ','เริ่มจากรายรับหรือรายจ่ายรายการแรก แล้วดูภาพรวมได้ที่นี่',button('บันทึกรายการแรก','add-transaction','secondary','plus')),link('ดูทั้งหมด','transactions','ghost small'))}</div><div class="section-stack">${card('งบเดือนนี้','ค่าใช้จ่ายที่ยืนยันแล้ว',budget().filter(b=>b.amount>0).slice(0,4).map((b,i)=>`<div class="budget-row"><div class="metric-row"><span>${esc(categoryLabel(b))}</span><strong>${baht(b.amount)}</strong></div>${progress(p.spendingLimit>0?b.amount/p.spendingLimit*100:0,['#24775d','#88b497','#d6bc8d','#8393bb'][i])}</div>`).join('')+`<div class="metric-row" style="margin-top:20px;padding-top:16px;border-top:1px solid var(--border)"><span>เหลือจัดสรร</span><strong class="${left<0?'negative':'positive'}">${baht(left)}</strong></div><p class="field-help">${unknown?`อีก ${unknown} หมวดยังไม่ยืนยัน รวมภาระ กยศ. จึงยังสรุปว่า 50% ทำได้แน่นอนไม่ได้`:'งบครบทุกหมวดแล้ว ตรวจรายจ่ายจริงทุกสัปดาห์'}</p>`,link('ปรับงบ','budget','ghost small'))}${card('เงินสำรองฉุกเฉิน',`เป้าหมาย ${settings().emergencyMonths} เดือนของค่าใช้จ่ายจำเป็น`,`<div class="metric-row"><strong class="value-large">${baht(settings().emergencyCurrent)}</strong>${tag('PHASE 1','success')}</div>${progress(e.progress)}<div class="metric-row" style="margin-top:12px"><span class="muted">เป้าหมาย ${e.complete?'':'เบื้องต้น '}</span><strong>${baht(e.target)}</strong></div><p class="field-help">${e.complete?(e.months===0?'เงินสำรองครบแล้ว':e.months===null?'กำหนดเงินออมเพื่อคำนวณเวลา':`ประมาณ ${e.months} เดือน เมื่อทำตามแผน`):'รอค่าใช้จ่ายจำเป็นครบ จึงคำนวณเป้าหมายและเวลาได้'}</p>`,link('ดูแผน','buckets','ghost small'))}</div></div>`+
 `<div class="grid-3">${card('บันทึกวันนี้','สร้างนิสัยเล็ก ๆ ที่ส่งผลระยะยาว',`<p>รายรับจริง ${baht(a.income)} · รายจ่ายจริง ${baht(a.expense)}</p>${link('เปิดสมุดรายวัน','transactions','ghost small','arrow')}`)}${card('มองไปข้างหน้า','ลองปรับเงินเดือนและรายได้เสริม',`<p>เปรียบเทียบการออม 1, 3, 5 และ 10 ปี</p>${link('จำลองอนาคต','projection','ghost small','arrow')}`)}${card('ปิดบัญชีทุกเดือน','เปลี่ยนตัวเลขให้เป็นภาพที่เข้าใจ',`<p>สรุปยอด เปรียบเทียบรายปี และพิมพ์ PDF</p>${link('เปิดรายงาน','reports','ghost small','arrow')}`)}</div>`;
}
function budgetView(){const p=planned(),a=ledger(),rows=budget();const unknown=rows.filter(b=>b.amount===null).length;return head('MONTHLY BUDGET','วางงบให้ทุกบาท','แผนงบของ '+monthName(month)+' · รายการจริงเชื่อมจากสมุดรายวัน',button('เพิ่มหมวด','add-category','secondary','plus'))+
 `<div class="stat-grid">${stat('วงเงินค่าใช้จ่าย',baht(p.spendingLimit),'หลังออมและรายการหัก','wallet',true)}${stat('งบที่ระบุแล้ว',baht(sum(rows.map(r=>r.amount))),unknown?`${unknown} หมวดยังไม่ระบุ`:'ครบทุกหมวด','layers')}${stat('ใช้จริงเดือนนี้',baht(a.expense),`${a.count} รายการในสมุดรายวัน`,'arrows')}${stat('เหลือจากวงเงิน',baht(p.spendingLimit===null?null:p.spendingLimit-a.expense),'วงเงิน − รายจ่ายจริง','chart')}</div>`+
 (p.remaining<0?notice(`งบเกินวงเงิน ${baht(-p.remaining)} เป้าออม ${pct(settings().savingsRate)} ยังไม่พอใช้ ลองลดรายจ่ายหรือลดออมเป็น 30–40% ชั่วคราว`,'warning'):unknown?notice('ยังไม่ยืนยันค่าใช้จ่ายบางหมวด โดยเฉพาะ กยศ. และค่าใช้จ่ายอื่น ใส่ 0 เฉพาะรายการที่ไม่มีจริง','warning'):'')+
 `<form id="budget-form">${card('งบประมาณ vs ใช้จริง','ตัวเลขเป็นบาทต่อเดือน · บันทึกแล้วแยกเก็บเฉพาะเดือนนี้',table(['หมวดค่าใช้จ่าย','ลักษณะ','จำเป็น','งบที่ตั้ง (฿)','ใช้จริง','คงเหลือ','สถานะ'],rows.map(r=>{const actual=num(a.byCategory[r.id]);const diff=r.amount===null?null:r.amount-actual;return [`<strong>${esc(categoryLabel(r))}</strong><div class="no-print">${button('ปรับหมวด','edit-category','ghost small','',`data-id="${esc(r.id)}"`)}</div>`,tag(r.type==='fixed'?'Fixed':'Variable'),r.essential?'จำเป็น':'ปรับลดได้',`<input class="amount-input" name="budget-${esc(r.id)}" aria-label="งบ ${esc(categoryLabel(r))}" type="number" min="0" max="1000000000" step="0.01" value="${r.amount??''}" placeholder="ยังไม่ระบุ">`,baht(actual),`<span class="${diff<0?'negative':'positive'}">${baht(diff)}</span>`,r.amount===null?tag('รอระบุ'):diff<0?tag('เกินงบ','danger'):tag('อยู่ในงบ','success')];}))+`<div class="page-actions no-print" style="margin-top:20px">${button('หมวดว่าง = ไม่มีค่าใช้จ่าย','zero-budget','secondary')}<button class="button primary" type="submit">${icon('check',17)}บันทึกงบเดือนนี้</button></div>`)} </form>`+
 `<div class="grid-2">${card('ค่าอาหาร: ทำให้ทำต่อได้','จากงบอาหารที่คุณตั้ง',`<div class="stat-value">${baht(rows.find(b=>b.id==='food')?.amount/30,0)} <small class="muted" style="font-size:14px">/ วัน</small></div><p>ใช้สมมติฐาน 30 วัน · ถ้าแบ่ง 3 มื้อ = ${baht(rows.find(b=>b.id==='food')?.amount/90,1)} ต่อมื้อ</p><p class="muted">เตรียมน้ำและอาหารบางมื้อ เลือกร้านใกล้ที่ทำงาน วางแผนซื้อวัตถุดิบ และรวมค่ากาแฟ/เดลิเวอรีไว้ในงบเดียวกัน งบ 100 บาทต่อวันค่อนข้างตึง ควรดูยอดจริงก่อนลดเพิ่ม</p>`)}${card('เมื่อเงินไม่พอ ให้ตัดตามลำดับ','กันสิ่งจำเป็นก่อน',`<ol><li>Subscription ซ้ำกัน / Cloud ที่ไม่ได้ใช้งาน</li><li>เดลิเวอรี ความบันเทิง งานสังคม และท่องเที่ยว</li><li>เลื่อนอุปกรณ์หรือคอร์สที่ไม่เร่งด่วน</li><li>ทบทวนที่พักและการเดินทางเมื่อหมดสัญญา</li><li>ลดเป้าออมเป็น 30–40% ชั่วคราว หากค่าใช้จ่ายจำเป็นยังเกิน</li></ol><p class="field-help">รายจ่ายรายปี ÷ 12 = เงินที่ควรกันต่อเดือน ระวังอย่านับค่า Cert ทั้งหมวดค่าใช้จ่ายและกองเป้าหมายซ้ำ</p>`)}</div>`;
}
function bucketsView(){const p=planned(),e=emergency();const isFunded=e.complete&&e.gap===0;const shares=isFunded?[0,settings().bucketSafePercent??30,settings().bucketInvestmentPercent??50,settings().bucketGoalsPercent??20]:[100,0,0,0];const names=['เงินสำรองฉุกเฉิน','ออมรักษาเงินต้น','ลงทุนระยะยาว','เป้าหมายเฉพาะ'];const subs=['สภาพคล่องสูง ใช้เมื่อจำเป็น','แยกบัญชีตามกำหนดใช้เงิน','เงินที่ไม่ต้องใช้ในระยะสั้น','Certificate / อุปกรณ์ / ท่องเที่ยว'];return head('BUCKET SYSTEM','เงินแต่ละกอง มีหน้าที่ของตัวเอง','แยกเงินสำรอง เงินออม และเงินลงทุน เพื่อเลือกความเสี่ยงให้ตรงกับเวลาที่ต้องใช้',link('แก้ไขยอดและสัดส่วน','settings','secondary','settings'))+
 notice(isFunded?'เงินสำรองครบตามข้อมูลที่ระบุแล้ว สัดส่วน Phase 3 ด้านล่างเป็นข้อเสนอให้ทบทวนตามเป้าหมาย':'Phase 1: เงินออมที่ตั้งไว้ทั้งหมดเข้ากองฉุกเฉินก่อน ส่วนค่า Cert ที่จำเป็นให้ตั้งงบในค่าใช้จ่าย','success')+
 `<div class="bucket-grid">${names.map((name,i)=>`<section class="bucket-card"><span class="stat-icon">${icon(['shield','bank','chart','target'][i],24)}</span><p class="eyebrow">BUCKET 0${i+1}</p><h2 class="card-title">${name}</h2><p class="muted">${subs[i]}</p><div class="stat-value">${baht(p.savings===null?null:p.savings*shares[i]/100)}</div><div class="metric-row"><span class="muted">ต่อเดือน</span>${tag(shares[i]+'% ของเงินออม',i===0?'success':'muted')}</div>${progress(shares[i])}</section>`).join('')}</div>`+
 `<div class="grid-2">${card('เป้าหมายเงินฉุกเฉิน',`${settings().emergencyMonths} × ค่าใช้จ่ายจำเป็นต่อเดือน`,table(['รายการ','จำนวน'],[['ค่าใช้จ่ายจำเป็นที่ระบุแล้ว',baht(sum(budget().filter(b=>b.essential).map(b=>b.amount)))],['เป้าหมายที่ยืนยันครบ',e.complete?baht(e.target):'รอระบุค่าใช้จ่ายที่ขาด'],['สะสมแล้ว',baht(settings().emergencyCurrent)],['เวลาโดยประมาณ',e.complete&&e.months!==null?`${e.months} เดือน`:'รอข้อมูลครบ']])+`<p class="field-help">หากเงินออมคงที่: CEILING(MAX(0, เป้าหมาย − มีแล้ว) ÷ เงินออมต่อเดือน) ระบบจำลองทีละเดือนเพื่อรวมเงินเดือนหลังโปรและการขึ้นรายปี ไม่รวมดอกเบี้ย</p>`)}${card('กองสำรองภาษี','เป็นเงินรอจ่ายภาษี ไม่ใช่ความมั่งคั่งที่ใช้ได้',`<div class="stat-value">${baht(settings().taxReserveMonthly)}</div><p>แยกจากยอดออม ${money(settings().savingsRate)}% โดยหักออกจากวงเงินใช้จ่ายเพิ่มเติม จึงไม่ทำให้ยอดออมดูสูงเกินจริง</p><p class="muted">ใช้ยอดภาษีคาดการณ์ทั้งปี หักภาษี ณ ที่จ่ายและภาษีที่จ่ายแล้ว หักเงินสำรองเดิม แล้วหารจำนวนเดือนที่จะกันเงิน</p>${link('คำนวณและนำไปใช้','tax','secondary','arrow')}`)}</div>`+
 card('ออมแบบรักษาเงินต้น กับ ลงทุน ควรแยกกัน','ผลตอบแทนที่คาดหวังไม่เท่ากับการรับประกัน',table(['เครื่องมือ','เงินต้น / ความเสี่ยง','สภาพคล่อง','ผลตอบแทนและข้อควรดู'],[['ออมทรัพย์ธนาคารที่อยู่ในระบบคุ้มครอง','คุ้มครองตามวงเงิน DPA รวม 1 ล้านบาท/คน/สถาบันการเงิน','ถอนง่าย เหมาะกับเงินฉุกเฉินส่วนแรก','ดูประกาศธนาคาร ณ วันฝาก รวมเพดานยอดเงินและเงื่อนไข'],['เงินฝากประจำ','เงินฝากที่เข้าเกณฑ์ DPA; ถอนก่อนกำหนดอาจเสียสิทธิดอกเบี้ย','ตามอายุเงินฝาก แบ่งหลายก้อนได้','อัตราตามสัญญา ต้องคำนึงภาษีดอกเบี้ย'],['กองทุนตลาดเงิน / ตราสารหนี้สั้น','ไม่รับประกันเงินต้น และไม่ใช่เงินฝาก','ตามเวลารับซื้อคืนของกองทุน','ผลตอบแทนผันแปร มีค่าธรรมเนียม; สมมติฐานจำลองต่ำ 2% ไม่ใช่อัตราตลาด'],['พันธบัตรออมทรัพย์รัฐบาล','คืนเงินต้นตามเงื่อนไขเมื่อครบกำหนด; ขายก่อนอาจขาดทุน','ขึ้นกับรุ่นและเงื่อนไขโอน/ขาย','ดอกเบี้ยต้องดูหนังสือชี้ชวนแต่ละรุ่น'],['พอร์ตลงทุนแบบสมดุล','มูลค่าลดลงและขาดทุนได้','ควรเป็นเงินระยะยาว','แบบจำลองใช้ 5% ต่อปี สมมติฐานก่อนภาษี/ค่าธรรมเนียม ไม่ใช่คำรับประกัน']])+`<p class="field-help">ไม่มีการดึงอัตราดอกเบี้ยสด ข้อมูลคุ้มครองเงินฝาก: <a target="_blank" rel="noopener" href="https://www.dpa.or.th/">สถาบันคุ้มครองเงินฝาก</a> · ข้อมูลกองทุน: <a target="_blank" rel="noopener" href="https://www.sec.or.th/">ก.ล.ต.</a></p>`)+
 `<div class="grid-3">${card('Phase 1 · ตั้งหลัก','เงินสำรองยังไม่ครบ','<p>โอนเงินออมทันทีเมื่อเงินเข้า สะสมเงินฉุกเฉินในบัญชีถอนง่าย และชำระหนี้ตามกำหนด</p>')}${card('Phase 2 · ตรวจความพร้อม','เงินสำรองครบและกระแสเงินสดเป็นบวก','<p>แยกเป้าหมายระยะสั้น ตรวจความคุ้มครองสุขภาพ ทบทวน กยศ. และกันภาษีให้พอ ก่อนเพิ่มความเสี่ยง</p>')}${card('Phase 3 · ลงทุนต่อเนื่อง','ใช้เงินที่ไม่จำเป็นต้องใช้เร็ว ๆ นี้','<p>กำหนดสัดส่วนสินทรัพย์ตามความเสี่ยง ทยอยลงทุนและทบทวนปีละครั้ง รักษากองฉุกเฉินไว้เสมอ</p>')}</div>`;
}
function categoryName(id){return categoryLabel(budget().find(b=>b.id===id))||({'salary':'เงินเดือน','side':'รายได้เสริม','other-income':'รายได้อื่น','emergency':'เงินฉุกเฉิน','safe':'ออมรักษาเงินต้น','invest':'ลงทุน','goal':'เป้าหมาย','tax':'สำรองภาษี'}[id])||id||'ไม่ระบุ';}
function transactionTable(rows,actions=true){return table(['วันที่','รายละเอียด','หมวด','ประเภท','ยอดเงิน',...(actions?['']:[])],rows.map(t=>[esc(t.date),`<strong>${esc(t.description)}</strong><div class="field-help">${esc(t.account||'')}</div>`,esc(categoryName(t.categoryId)),tag({income:'รายรับ',expense:'รายจ่าย',transfer:'โอนระหว่างกอง'}[t.type],{income:'success',expense:'muted',transfer:'warning'}[t.type]),`<strong class="${t.type==='income'?'positive':t.type==='expense'?'negative':''}">${t.type==='income'?'+':t.type==='expense'?'−':''}${baht(t.amount,2)}</strong>`,...(actions?[`<div class="no-print">${editActions('transaction',t.id)}</div>`]:[])]));}
function transactionsView(){const a=ledger();const rows=state.transactions.filter(t=>t.date.startsWith(month)&&(transactionType==='all'||t.type===transactionType)&&[t.description,t.account,categoryName(t.categoryId)].join(' ').toLowerCase().includes(transactionSearch.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));const pages=Math.max(1,Math.ceil(rows.length/50));transactionPage=Math.min(transactionPage,pages-1);return head('TRANSACTIONS','สมุดรายรับ–รายจ่าย','บันทึกวันละนิด เห็นเงินชัดทั้งเดือน · '+monthName(month),button('ส่งออก CSV','transactions-csv','secondary','down')+button('เพิ่มรายการ','add-transaction','primary','plus'))+
 `<div class="stat-grid">${stat('รายรับจริง',baht(a.income),'เงินเข้าบัญชีในเดือนนี้','arrows')}${stat('รายจ่ายจริง',baht(a.expense),'ไม่นับการโอนระหว่างบัญชีตนเอง','wallet')}${stat('กระแสเงินสดสุทธิ',baht(a.net),'รายรับ − รายจ่าย','chart',true)}${stat('โอนระหว่างกอง',baht(a.transfers),'ไม่บวกเป็นรายรับหรือรายจ่ายซ้ำ','layers')}</div>`+
 card('รายการทั้งหมด',`${rows.length} รายการ · หน้า ${transactionPage+1}/${pages}`,`<div class="page-actions no-print" style="justify-content:flex-start;margin-bottom:20px"><input id="transaction-search" type="search" aria-label="ค้นหารายการ" placeholder="ค้นหารายการหรือหมวด…" value="${esc(transactionSearch)}"><select id="transaction-type" aria-label="ประเภทที่แสดง">${[['all','ทุกประเภท'],['income','รายรับ'],['expense','รายจ่าย'],['transfer','โอนระหว่างกอง']].map(([v,l])=>`<option value="${v}" ${transactionType===v?'selected':''}>${l}</option>`).join('')}</select></div>${rows.length?transactionTable(rows.slice(transactionPage*50,transactionPage*50+50)):empty('ยังไม่มีรายการที่ตรงกัน','เพิ่มรายการหรือเปลี่ยนเดือนเพื่อดูประวัติ')}${pages>1?`<div class="page-actions no-print">${button('ก่อนหน้า','transaction-page','secondary small','',`data-page="${Math.max(0,transactionPage-1)}"`)}${button('ถัดไป','transaction-page','secondary small','',`data-page="${Math.min(pages-1,transactionPage+1)}"`)}</div>`:''}`)+notice('รายการโอนใช้บันทึกการย้ายเงินระหว่างบัญชีของคุณเท่านั้น ยอดกองฉุกเฉิน เป้าหมาย และงบทรัพย์สินให้ยืนยันยอดจริงแยกต่างหาก เพื่อไม่ให้เกิดการนับเงินซ้ำ');
}
