function taxInput(){const p=planData(),s=settings(),t=p.tax;const forecast=t.mode!=='annual';const probation=Math.max(0,Math.min(12,num(s.probationMonths)));const salary=forecast?(s.salary===null?null:s.salary*probation+(s.salaryAfterProbation??s.salary)*(12-probation)+num(s.bonusAnnual)):t.salaryAnnual;return {taxYear:Number(year()),incomes:[{type:'40(1)',amount:salary,withheld:forecast?num(s.monthlyWithheld)*12:num(t.salaryWithheld),expense:0},...p.streams.map(i=>({type:i.type,amount:i.amount,expense:i.expense,withheld:i.withheld}))],socialSecurity:forecast?(s.socialSecurityMonthly===null?F.estimateSocialSecurity(s.salary,Number(year()))*12:s.socialSecurityMonthly*12):t.ssoAnnual,personalAllowance:60000,deductions:t.deductions,taxPaidMidYear:num(t.taxPaidMidYear),reserveExisting:num(t.reserveExisting),monthsRemaining:num(t.monthsRemaining)||12};}
