window.addEventListener('afterprint',()=>{printDetails.forEach(d=>{d.open=false;setTimeout(()=>delete d.dataset.printing,0);});printDetails=[];});
bootCloud();
Promise.allSettled([fetch('./workbook-reference.json').then(r=>{if(!r.ok)throw new Error('reference');return r.json();}),fetch('./finance-notes.json').then(r=>{if(!r.ok)throw new Error('notes');return r.json();})]).then(([a,b])=>{if(a.status==='fulfilled')ref=a.value;if(b.status==='fulfilled')notes=b.value;if(cloudReady&&['workbook','tax','guide'].includes(page))renderPage();});

function cloudSummary(data){return data?`${data.transactions.length} รายการ · แผน ${Object.keys(data.plans).length} ปี · ${data.goals.length} เป้าหมาย`:'ยังไม่มีข้อมูล';}
function renderAccountGate(){closeDrawer(false);formEditing=false;
 const signed=!!cloud;
 const fields=authMode==='recover'?'<div class="field"><label for="auth-password">รหัสผ่านใหม่ (อย่างน้อย 12 ตัวอักษร)</label><input id="auth-password" name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></div>':
 '<div class="field"><label for="auth-email">อีเมล</label><input id="auth-email" name="email" type="email" autocomplete="username" required></div>'+(authMode==='login'?'<div class="field"><label for="auth-password">รหัสผ่าน</label><input id="auth-password" name="password" type="password" autocomplete="current-password" required></div>':'');
 const label=authMode==='recover'?'บันทึกรหัสผ่านใหม่':authMode==='reset'?'ส่งลิงก์ตั้งรหัสผ่าน':'เข้าสู่ระบบ';
 const login=configured?'<form id="auth-form" class="form-grid">'+fields+'<button type="submit" class="button primary">'+label+'</button></form><div class="page-actions">'+button(authMode==='login'?'ลืมรหัสผ่าน':'กลับหน้าเข้าสู่ระบบ',authMode==='login'?'auth-reset':'auth-login','ghost')+'</div>':'<div class="notice"><div>ยังไม่ได้เชื่อมฐานข้อมูล โปรดทำตามคู่มือตั้งค่า Supabase และ GitHub Pages ก่อนเริ่มใช้งาน</div></div><p><a href="./setup.html">เปิดคู่มือติดตั้งทีละขั้น</a></p>';
 const begin=signed?'<p>บัญชีนี้ยังไม่มีสมุดการเงินบนคลาวด์ เลือกข้อมูลเริ่มต้นเพียงครั้งเดียว</p>'+(localStorage.getItem(STORAGE_KEY)?'<p>พบข้อมูลเดิมในเครื่อง: '+cloudSummary(state)+'</p>'+button('สำรองและย้ายข้อมูลเดิมขึ้นบัญชี','cloud-migrate','primary'):'')+button('นำเข้าไฟล์สำรอง JSON','cloud-import')+button('เริ่มจากแผนว่าง','cloud-new')+'<p class="field-help">ข้อมูลเดิมยังคงอยู่ในเครื่อง การนำเข้าจะเก็บข้อมูลการเงินในบัญชี Supabase ของคุณ</p>':login;
 $('#app').innerHTML='<main class="content auth-shell"><div class="auth-language">'+languageButton()+'</div>'+head('SATI · PERSONAL WORKSPACE','เงินของคุณ เชื่อมถึงกัน','สมุดการเงินเดียวกัน ทั้งมือถือและคอม')+card(signed?'พร้อมเชื่อมสมุดการเงิน':label,signed?esc(cloud.user.email):'เข้าสู่ระบบด้วยอีเมลเดียวกันในทุกอุปกรณ์','<p role="status">'+esc(cloudMessage)+'</p><div class="onboarding-actions">'+begin+'</div>')+'</main>';
}
async function handleAuthForm(form){
 const f=new FormData(form),submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='กำลังดำเนินการ…';
 try{
   if(authMode==='login'){await signIn(f.get('email').trim(),f.get('password'));await bootCloud();}
   else if(authMode==='reset'){await resetPassword(f.get('email').trim());cloudMessage='หากอีเมลนี้มีสิทธิ์ใช้งาน โปรดตรวจลิงก์ตั้งรหัสผ่านในอีเมล';renderAccountGate();}
   else {await changePassword(f.get('password'));authMode='login';history.replaceState(null,'',location.pathname);await bootCloud();}
 }catch(e){cloudMessage=e.message;renderAccountGate();}finally{submit.disabled=false;}
}

function accountView(){
 const r=cloud.session.record,c=cloud.session.conflict;
 return head('ACCOUNT & SYNC','บัญชีและการซิงก์','เข้าสู่ระบบบัญชีเดียวกันบนทุกอุปกรณ์ แล้วเปิดเว็บลิงก์เดียวกัน')+
 card('บัญชีของคุณ',esc(cloud.user.email),`<p>ฐานข้อมูลออนไลน์: Supabase PostgreSQL</p><p>ข้อมูลแยกตามบัญชี ตรวจสิทธิ์ที่เซิร์ฟเวอร์ทุกครั้ง</p><p>${esc(cloudMessage)} · รุ่นข้อมูล ${r.revision}</p><div class="page-actions">${button('ซิงก์ตอนนี้','cloud-sync','primary')}${button('สำรอง JSON','backup')}${button('สำรองและออกจากระบบ','cloud-logout')}</div>`)+
 (c?card('พบการแก้ไขจากอีกเครื่อง','ระบบหยุดซิงก์เพื่อป้องกันข้อมูลทับกัน',`<p>ในเครื่อง: ${cloudSummary(r.data)}</p><p>บนคลาวด์: ${cloudSummary(c.data)} · รุ่น ${c.revision}</p><p>เลือกชุดที่จะเก็บ ระบบจะดาวน์โหลดสำรองทั้งสองชุดก่อนแทนที่ ไม่มีการรวมรายการอัตโนมัติ</p><div class="page-actions">${button('ใช้ข้อมูลบนคลาวด์','cloud-remote','primary')}${button('ใช้ข้อมูลในเครื่องแทน','cloud-local')}</div>`):'')+
 card('วิธีใช้สองอุปกรณ์','สถานะ “ซิงก์แล้ว” หมายถึงเซิร์ฟเวอร์รับข้อมูลแล้ว',`<ol><li>บนเครื่องแรก เลือกย้ายข้อมูลเดิมหรือเริ่มแผน แล้วรอ “ซิงก์แล้ว”</li><li>เปิดเว็บเดียวกันบนมือถือ เข้าด้วยบัญชีอีเมล เดียวกัน</li><li>เมื่อออนไลน์ ระบบตรวจข้อมูลทุก 10 วินาที และเมื่อกลับมาที่แท็บ</li><li>ระหว่างแก้ฟอร์ม ระบบพักการดึงข้อมูลเพื่อรักษาข้อมูลที่กำลังพิมพ์ บันทึกหรือเปลี่ยนหน้าก่อนรับข้อมูลใหม่</li></ol><p>หากเน็ตหลุดหลังเปิดสมุดแล้ว ยังบันทึกค้างในเครื่องได้และจะส่งเมื่อกลับมาออนไลน์ การเปิดใหม่ต้องตรวจบัญชีผ่านอินเทอร์เน็ตก่อน</p><p>รองรับข้อมูลซิงก์รวมไม่เกิน 4.5 MB ในรุ่นนี้ หากเกินจะแจ้งเตือนและไม่ลบข้อมูลในเครื่อง สำรอง JSON อย่างสม่ำเสมอ</p><p>แคชในเบราว์เซอร์ไม่ได้เข้ารหัสเพิ่มเติม ควรล็อกอุปกรณ์และออกจากระบบเมื่อใช้เครื่องร่วมกัน</p>`);
}
function updateCloudStatus(){const el=$('#cloud-status');if(!el||!cloud)return;el.innerHTML=`<div>${esc(cloudMessage)} ${cloud.session.conflict?'<a href="#account">ตรวจและเลือกข้อมูล</a>':'<a href="#account">บัญชีและการซิงก์</a>'}</div>`;}
async function bootCloud(){
 cloudReady=false;cloudBlocked=false;cloudMessage='กำลังตรวจบัญชีและโหลดข้อมูล…';if(authMode==='recover'){renderAccountGate();return;}renderLoading();
 try{
   cloud=await connectCloud({validate:validateBackup,onChange:record=>{
     if(!cloudReady||localSaving)return;
     if(record.data&&JSON.stringify(state)!==JSON.stringify(record.data)){state=structuredClone(record.data);shell();}
   }});
   if(cloud.session.record.data){state=structuredClone(cloud.session.record.data);cloudReady=true;storageProblem='';cloudMessage=cloud.session.conflict?'ข้อมูลต่างกันระหว่างเครื่อง กรุณาเลือกชุดข้อมูล':cloud.session.record.dirty?'มีข้อมูลในเครื่องรอส่ง':'ซิงก์แล้ว';shell();if(!cloud.session.conflict)await syncNow();}
   else {cloudMessage='เข้าสู่ระบบแล้ว · ยังไม่เคยตั้งค่าข้อมูลบนคลาวด์';renderAccountGate();}
 }catch(e){cloud=null;cloudMessage=e.message;renderAccountGate();}
}
async function syncNow(){
 if(!cloudReady||cloudBlocked||cloud.session.busy)return;
 try{
   cloudMessage='กำลังซิงก์…';updateCloudStatus();
   await cloud.session.sync({allowPull:!formEditing});
   cloudMessage=cloud.session.conflict?'พบการแก้ไขจากอีกเครื่อง กรุณาเลือกข้อมูล':cloud.session.record.dirty?'บันทึกในเครื่องแล้ว · รอส่ง':'ซิงก์แล้ว';
 }catch(e){if(e.status===401){cloudBlocked=true;cloudMessage='บัญชีหมดอายุหรือเปลี่ยนแล้ว กรุณารีเฟรชและเข้าสู่ระบบใหม่';}else cloudMessage=cloud.session.conflict?'พบการแก้ไขจากอีกเครื่อง กรุณาเลือกข้อมูล':`ยังไม่ซิงก์ · ${e.message}`;}
 updateCloudStatus();if(page==='account'&&!$('#modal-root .modal'))renderPage();
}
async function handleCloudAction(act){try{
 if(act==='cloud-retry'){await bootCloud();return;}
 if(act==='cloud-import'){const file=document.createElement('input');file.type='file';file.accept='.json,application/json';file.onchange=async()=>{try{const selected=file.files[0];if(!selected)return;if(selected.size>4_500_000)throw new Error('ไฟล์ใหญ่เกิน 4.5 MB');const imported=validateBackup(JSON.parse(await selected.text()));confirmation('นำข้อมูลนี้ขึ้นบัญชี?',cloudSummary(imported)+' จะถูกบันทึกในบัญชี '+esc(cloud.user.email),()=>{state=imported;cloud.session.edit(state);cloudReady=true;storageProblem='';shell();syncNow();});}catch(e){toast(e.message);}};file.click();return;}
 if(act==='cloud-sync'){await syncNow();return;}
 if(act==='cloud-migrate'||act==='cloud-new'){
   if(!cloud||cloud.session.record.data)return;
   if(act==='cloud-migrate'){state=validateBackup(JSON.parse(localStorage.getItem(STORAGE_KEY)));backup('-before-cloud');}
   else state=defaultState(year());
   cloud.session.edit(state);cloudReady=true;storageProblem='';cloudMessage='กำลังซิงก์ข้อมูลตั้งต้น…';shell();await syncNow();return;
 }
 if(act==='cloud-remote'||act==='cloud-local'){
   if(!cloud.session.conflict)return;
   confirmation('เลือกข้อมูลชุดนี้?', 'ดาวน์โหลดสำรองข้อมูลในเครื่องและบนคลาวด์ก่อนแทนที่ หากมีรายการสำคัญอยู่ทั้งสองชุด ให้นำมาเปรียบเทียบก่อนเลือก',()=>{
     backup('-local-conflict');download(`sati-cloud-conflict-${now}.json`,JSON.stringify(cloud.session.conflict.data,null,2),'application/json');
     if(act==='cloud-remote')cloud.session.useRemote();else cloud.session.useLocal();
     state=structuredClone(cloud.session.record.data);shell();syncNow();
   });return;
 }
 if(act==='cloud-logout')confirmation('สำรองและออกจากระบบ?', 'ระบบจะดาวน์โหลดข้อมูลปัจจุบันก่อนออกจากระบบ หากมีข้อมูลยังไม่ซิงก์ ให้เก็บไฟล์นี้ไว้เพื่อนำกลับภายหลัง',()=>{performLogout();});

 }catch(e){cloudMessage=e.message;toast(e.message);updateCloudStatus();}}
setInterval(()=>{if(document.visibilityState==='visible')syncNow();},10000);
window.addEventListener('online',()=>syncNow());
window.addEventListener('focus',()=>syncNow());
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')syncNow();});
window.addEventListener('beforeunload',e=>{if(cloud?.session.record?.dirty){e.preventDefault();e.returnValue='';}});


async function performLogout(){
 try{backup('-before-signout');const key=cloud.key;await signOut();localStorage.removeItem(key);localStorage.removeItem(key+'-previous');cloud=null;cloudReady=false;cloudBlocked=true;location.assign(location.pathname);}
 catch(e){toast('ออกจากระบบไม่สำเร็จ: '+e.message);}
}
authClient?.auth.onAuthStateChange((event,session)=>{
 if(event==='PASSWORD_RECOVERY'){authMode='recover';cloudReady=false;setTimeout(renderAccountGate,0);}
 if(cloud&&(!session||session.user.id!==cloud.user.id)){cloudReady=false;cloudBlocked=true;cloud=null;cloudMessage='บัญชีเปลี่ยนแล้ว กรุณาเข้าสู่ระบบใหม่';setTimeout(renderAccountGate,0);}
});

let installPrompt=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('appinstalled',()=>{installPrompt=null;toast('เพิ่ม SATI เป็นแอปแล้ว');});
function tutorialIndex(){try{const n=localStorage.getItem('sati-tutorial');return n===null?null:Math.max(0,Math.min(steps.length-1,Number(n)||0));}catch{return null;}}
function renderTutorial(){const i=tutorialIndex();if(i===null)return;const [route,title,desc]=steps[i];const panel=document.createElement('section');panel.className='tutorial-panel no-print';panel.setAttribute('aria-label','บทสอนเริ่มต้น');panel.innerHTML='<div><span class="eyebrow">ขั้นตอน '+(i+1)+' / '+steps.length+'</span><h2>'+title+'</h2><p>'+desc+'</p><small>กดบันทึกในหน้านั้นก่อน แล้วค่อยไปขั้นถัดไป การกดถัดไปไม่บันทึกข้อมูลให้</small></div><div class="page-actions">'+(page!==route?'<a class="button primary" href="#'+route+'">เปิดหน้าที่ต้องใช้</a>':'')+(i?'<button class="button secondary" data-action="tutorial-prev">ย้อนกลับ</button>':'')+'<button class="button primary" data-action="tutorial-next">'+(i===steps.length-1?'จบบทสอน':'ขั้นถัดไป')+'</button><button class="button ghost" data-action="tutorial-end">พักบทสอน</button></div>';$('#view').prepend(panel);}
document.addEventListener('click',async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action==='install-app'){if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();await prompt.userChoice;}else{const message='เปิดเมนู Chrome ⋮ → เพิ่มลงในหน้าจอหลัก / ติดตั้งแอป แล้วเปิดจากไอคอน SATI';const hint=$('#install-hint');if(hint)hint.textContent=message;else toast(message);}return;}if(!action.startsWith('tutorial-'))return;let i=tutorialIndex()??0;if(action==='tutorial-start')i=0;if(action==='tutorial-prev')i=Math.max(0,i-1);if(action==='tutorial-next')i++;try{if(action==='tutorial-end'||i>=steps.length){localStorage.removeItem('sati-tutorial');renderPage();toast(i>=steps.length?'พร้อมแล้ว ใช้สมุดรายวันต่อได้เลย':'กลับมาเริ่มบทสอนได้ที่คู่มือ');return;}localStorage.setItem('sati-tutorial',String(i));}catch{toast('เบราว์เซอร์ไม่อนุญาตให้จำบทสอน เปิดคู่มือเพื่อทำตามขั้นตอนได้');return;}if(page===steps[i][0])renderPage();else location.hash=steps[i][0];});

function navigationMarkup(){const essential=['dashboard','transactions','budget','buckets','goals','guide','settings'];const item=([id,ico,label])=>'<a class="nav-item '+(id===page?'active':'')+'" href="#'+id+'" '+(id===page?'aria-current="page"':'')+'><span class="nav-icon">'+icon(ico,18)+'</span><span class="nav-text">'+label+'</span></a>';return '<div class="nav-label">ใช้ประจำ</div>'+essential.map(id=>item(nav.find(n=>n[0]===id))).join('')+'<details class="nav-more" '+(!essential.includes(page)?'open':'')+'><summary>วางแผนและเครื่องมือเพิ่มเติม</summary>'+nav.filter(n=>!essential.includes(n[0])).map(item).join('')+'</details>';}

document.addEventListener('click',e=>{if(e.target.closest('[data-action]')?.dataset.action!=='language')return;if(formEditing||cloud?.session.record?.dirty||$('#modal-root .modal')){toast(getLanguage()==='en'?'Save your edits and close the dialog before switching languages.':'กรุณาบันทึกข้อมูลและปิดหน้าต่างก่อนสลับภาษา');return;}if(setLanguage(getLanguage()==='en'?'th':'en'))location.reload();else toast(getLanguage()==='en'?'Your browser cannot save the language preference.':'เบราว์เซอร์ไม่สามารถจำภาษาที่เลือกได้');});
